import openpyxl
from datetime import datetime

wb = openpyxl.load_workbook('output.xlsx')
ws = wb['Sheet1']

# Group rows by (A, B)
groups = {}
for r in range(3, ws.max_row + 1):
    a = ws.cell(r, 1).value
    b = ws.cell(r, 2).value
    groups.setdefault((a, b), []).append(r)

# For each group, find max date in column E. Keep rows where E == max date.
# Delete rows where E is empty (None) or E < max date.
for (a, b), rows in groups.items():
    max_date = None
    for r in rows:
        d = ws.cell(r, 5).value
        if d is not None:
            if max_date is None or d > max_date:
                max_date = d
    for r in rows:
        d = ws.cell(r, 5).value
        if d is None or d != max_date:
            ws.delete_rows(r, 1)

wb.save('output.xlsx')
print("done")
